sys_ws_operation.operation_script:
(function process(request, response) {
    var startTime = new GlideDateTime();
    var httpStatus = 200;
    var responseBody = {};
    var caseId = '';

    try {
        var requestData = request.body.data;

        // Validate required fields
        var missing = [];
        if (!requestData.torq_incident_id) missing.push('torq_incident_id');
        if (!requestData.short_description) missing.push('short_description');
        if (!requestData.severity) missing.push('severity');

        if (missing.length > 0) {
            httpStatus = 400;
            responseBody = {
                error: {
					code: httpStatus,
                    message: 'Missing required fields',
                    details: 'The following fields are required: ' + missing.join(', ')
                }
            };
            response.setStatus(400);
            response.setBody(responseBody);
            _logWebhook(request, responseBody, httpStatus, startTime, caseId);
            return;
        }

        // Look up existing case by torq_incident_id
        var gr = new GlideRecord('x_2241073_securi_0_sec_case');
        gr.addQuery('torq_incident_id', requestData.torq_incident_id);
        gr.query();

        var isNew = !gr.next();
        if (isNew) {
            gr.initialize();
        }

        // Map required fields
        gr.setValue('torq_incident_id', requestData.torq_incident_id);
        gr.setValue('short_description', requestData.short_description);
        gr.setValue('severity', requestData.severity.toString());
        gr.setValue('case_source', 'torq');

        // Map optional fields
        var optionalFields = {
            'description': 'description',
            'category': 'category',
            'subcategory': 'subcategory',
            'detection_source': 'detection_source',
            'torq_incident_url': 'torq_incident_url',
            'case_type': 'case_type',
            'affected_systems': 'affected_systems',
            'affected_users': 'affected_users',
			'priority': 'priority'
        };

        for (var key in optionalFields) {
            if (requestData.hasOwnProperty(key) && requestData[key] !== null && requestData[key] !== undefined) {
                gr.setValue(optionalFields[key], requestData[key].toString());
            }
        }

        if (isNew) {
            caseId = gr.insert();
            httpStatus = 201;
        } else {
            gr.update();
            caseId = gr.getUniqueValue();
            httpStatus = 200;
        }

        // Re-read to get the auto-generated number
        var resultGR = new GlideRecord('x_2241073_securi_0_sec_case');
        resultGR.get(caseId);

        responseBody = {
            result: {
				case_number: resultGR.getValue('number'),
                sys_id: caseId,
                state: resultGR.getValue('state'),
                assigned_to: resultGR.getDisplayValue('assigned_to'),
				assignment_group: resultGR.getDisplayValue('assignment_group'),
				sla_due_date: resultGR.getValue('sla_due')
            }
        };

        response.setStatus(httpStatus);
        response.setBody(responseBody);

    } catch (e) {
        httpStatus = 500;
        responseBody = {
            error: {
				code: httpStatus,
                message: 'Internal server error',
                details: e.toString()
            }
        };
        response.setStatus(500);
        response.setBody(responseBody);
    }

    _logWebhook(request, responseBody, httpStatus, startTime, caseId);

})(request, response);

function _logWebhook(request, responseBody, httpStatus, startTime, caseId) {
    try {
        var endTime = new GlideDateTime();
        var duration = GlideDateTime.subtract(startTime, endTime);
        var durationMs = duration.getNumericValue();

        var log = new GlideRecord('x_2241073_securi_0_webhook_log');
        log.initialize();
        log.setValue('direction', 'inbound');
        log.setValue('endpoint_url', request.uri);
        log.setValue('http_method', 'POST');
        log.setValue('http_status', httpStatus);
        log.setValue('payload', request.body.dataString || '');
        log.setValue('response_body', JSON.stringify(responseBody));
        log.setValue('status', httpStatus < 400 ? 'success' : 'failure');
        log.setValue('duration_ms', durationMs);
        if (caseId) {
            log.setValue('case_id', caseId);
        }
        log.insert();
    } catch (e) {
        gs.error('Failed to log webhook: ' + e.toString());
    }
}
